"""
RAILTRACER - THE CONDUCTOR'S KNIFE   (Blender 3.x-5.x -> Unity FBX)
Run in Blender (Scripting tab), or headless:  blender -b --python railtracer_knife.py -- --out <folder>

  Prop_Knife   a vintage hunting knife, 0.34 m long. Pivot = the middle of the grip (where the fist closes), blade
               up (Blender +Z = Unity +Y), the flats facing Blender +-Y, the cutting edge on Blender -X, the spine on +X.
               Blade: polished steel (Trn_Steel, mirror-smooth), single-edged with a full flat grind, a small choil by
               the guard and an upswept curved tip. A thin brass guard; stacked spacers (black, brass, red) at both
               ends of the handle; jigged stag scales (Trn_Stag) with two brass pins; an aluminium bird's-head pommel
               hooking towards the edge side. Render-only (no collider): it rides in the player's hand.
"""
# Generated by stylized-blender-assets. Run in Blender (Scripting tab > Run Script) or:
#   blender --python THIS_FILE.py                      (open Blender with the scene built)
#   blender -b --python THIS_FILE.py -- --out <folder>   (headless export)

# ======================================================================
# CONFIG  -  edit these
# ======================================================================
# >>> CONFIG
EXPORT_DIR = r"C:\Users\owner\RailTracer\Assets\RailTracer\Train Assets\Knife"
KIT_NAME = "RailTracerKnife"
TEXTURE_STYLE = globals().get("TEXTURE_STYLE", "pbr")   # "flat" | "toon" | "painted" | "pbr"
BLADE = 0.19         # blade length (m)
SCALES = 0.072       # the stag part of the handle (m)
# <<< CONFIG

# Unity editor tools, installed into the Unity project that contains the export folder.
UNITY_TOOLS = {
    'KitBridge': '// Kit Bridge - build kits from inside Unity. Installed automatically by stylized-blender-assets kit scripts.\n//\n// Kit scripts live in Assets/KitScripts (the record of what built each asset folder).\n//   Tools > Kit > Build Kit Script...  pick a kit .py -> confirm -> Blender runs it in the background,\n//                                      then Unity refreshes; KitSetup makes the materials and the FBX\n//                                      files import with colliders.\n//   Tools > Kit > Rebuild Last Kit\n//   Tools > Kit > Bridge Settings...   Blender path; optional: watch the Downloads folder (OFF by default)\n//                                      so a downloaded kit script offers itself (Build / Ignore).\n// When Claude Code builds a kit it writes the script into Assets/KitScripts and runs Blender itself;\n// the bridge never auto-builds from that folder, so nothing is built twice.\n// Nothing ever runs without your click.\nusing System;\nusing System.Collections.Generic;\nusing System.Diagnostics;\nusing System.IO;\nusing System.Linq;\nusing System.Text.RegularExpressions;\nusing UnityEditor;\nusing UnityEngine;\nusing Debug = UnityEngine.Debug;\n\n[InitializeOnLoad]\npublic static class KitBridge\n{\n    const string Marker = "# Generated by stylized-blender-assets";\n    const string PrefBlender = "KitBridge.BlenderPath";\n    const string PrefWatch = "KitBridge.WatchDownloads";\n    const string PrefLast = "KitBridge.LastScript";\n\n    // path|timestamp already offered; SessionState survives script recompiles (no repeat dialogs)\n    static bool Handled(string key) => SessionState.GetBool("KitBridge:" + key, false);\n    static void MarkHandled(string key) => SessionState.SetBool("KitBridge:" + key, true);\n    static readonly List<string> output = new List<string>();\n    static Process running;\n    static string runningKit, runningOut;\n    static double nextPoll, startTime;\n\n    static KitBridge() { EditorApplication.update += Update; }\n\n    public static bool WatchDownloads\n    {\n        get => EditorPrefs.GetBool(PrefWatch, false);\n        set => EditorPrefs.SetBool(PrefWatch, value);\n    }\n\n    public static string DownloadsDir =>\n        Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Downloads");\n\n    static string AssetsFull => Norm(Application.dataPath);\n    static string ScriptsDir => AssetsFull + "/KitScripts";\n\n    static string Norm(string p) => Path.GetFullPath(p).Replace(\'\\\\\', \'/\').TrimEnd(\'/\');\n\n    // ------------------------------------------------------------------ polling\n    static void Update()\n    {\n        if (running != null)\n        {\n            float t = (float)((EditorApplication.timeSinceStartup - startTime) / 60.0);\n            if (EditorUtility.DisplayCancelableProgressBar("Kit Bridge",\n                    $"Blender is building {runningKit}...", Mathf.Clamp01(t)))\n            {\n                try { running.Kill(); } catch { }\n            }\n            if (running.HasExited) Finish();\n            return;\n        }\n        if (EditorApplication.timeSinceStartup < nextPoll) return;\n        nextPoll = EditorApplication.timeSinceStartup + 2.0;\n        if (EditorApplication.isCompiling || EditorApplication.isUpdating ||\n            EditorApplication.isPlayingOrWillChangePlaymode) return;\n\n        if (WatchDownloads) Scan(DownloadsDir);\n    }\n\n    static void Scan(string dir)\n    {\n        if (!Directory.Exists(dir)) return;\n        string[] files;\n        try { files = Directory.GetFiles(dir, "*.py"); } catch { return; }\n        foreach (var f in files)\n        {\n            DateTime stamp;\n            try { stamp = File.GetLastWriteTimeUtc(f); } catch { continue; }\n            string key = Norm(f) + "|" + stamp.Ticks;\n            if (Handled(key)) continue;\n            if ((DateTime.UtcNow - stamp).TotalSeconds < 1.5) continue;          // still downloading\n            MarkHandled(key);\n            if (!IsKitScript(f)) continue;\n            Offer(f);\n            return;                                                             // one dialog at a time\n        }\n    }\n\n    static bool IsKitScript(string path)\n    {\n        try\n        {\n            using (var r = new StreamReader(path))\n            {\n                for (int i = 0; i < 300 && !r.EndOfStream; i++)\n                    if (r.ReadLine().StartsWith(Marker)) return true;\n            }\n        }\n        catch { }\n        return false;\n    }\n\n    // ------------------------------------------------------------------ offer + run\n    public static void Offer(string script)\n    {\n        string text = File.ReadAllText(script);\n        string kit = Grab(text, @"^KIT_NAME\\s*=\\s*r?[""\']([^""\']*)[""\']") ?? Path.GetFileNameWithoutExtension(script);\n        string exportDir = Grab(text, @"^EXPORT_DIR\\s*=\\s*r?[""\']([^""\']*)[""\']") ?? "";\n        string outDir = ResolveOut(exportDir, kit, out string note);\n        string rel = "Assets" + outDir.Substring(AssetsFull.Length);\n\n        int choice = EditorUtility.DisplayDialogComplex("Kit Bridge",\n            $"Build kit \\"{kit}\\"?\\n\\nScript: {Path.GetFileName(script)}\\nExport to: {rel}{note}\\n\\n" +\n            "Blender runs the script in the background; the FBX files and materials then import here.",\n            "Build", "Ignore", "Settings...");\n        if (choice == 1) return;\n        if (choice == 2) { KitBridgeSettings.Open(); return; }\n\n        string archived = Archive(script);\n        Run(archived, kit, outDir);\n    }\n\n    static string Grab(string text, string pattern)\n    {\n        var m = Regex.Match(text, pattern, RegexOptions.Multiline);\n        return m.Success ? m.Groups[1].Value : null;\n    }\n\n    static string ResolveOut(string exportDir, string kit, out string note)\n    {\n        note = "";\n        if (!string.IsNullOrWhiteSpace(exportDir))\n        {\n            try\n            {\n                string full = Norm(exportDir);\n                if (full.StartsWith(AssetsFull + "/", StringComparison.OrdinalIgnoreCase) ||\n                    string.Equals(full, AssetsFull, StringComparison.OrdinalIgnoreCase))\n                    return AssetsFull + full.Substring(AssetsFull.Length);\n                note = $"\\n(The script\'s EXPORT_DIR is outside this project: {exportDir})";\n            }\n            catch { }\n        }\n        return AssetsFull + "/KitExports/" + kit;\n    }\n\n    static string Archive(string script)\n    {\n        Directory.CreateDirectory(ScriptsDir);\n        string name = Regex.Replace(Path.GetFileName(script), @"\\s*\\(\\d+\\)(?=\\.py$)", "");   // "kit (1).py" -> "kit.py"\n        string dest = ScriptsDir + "/" + name;\n        if (Norm(script) != dest)\n        {\n            File.Copy(script, dest, true);\n            if (Norm(Path.GetDirectoryName(script)) != ScriptsDir)\n                try { File.Delete(script); } catch { }\n        }\n        MarkHandled(dest + "|" + File.GetLastWriteTimeUtc(dest).Ticks);\n        return dest;\n    }\n\n    public static void Run(string script, string kit, string outDir)\n    {\n        string blender = FindBlender();\n        if (blender == null)\n        {\n            EditorUtility.DisplayDialog("Kit Bridge", "Blender was not found. Pick blender.exe (or the Blender app) next.", "OK");\n            blender = EditorUtility.OpenFilePanel("Locate Blender", "", "");\n            if (string.IsNullOrEmpty(blender)) return;\n            EditorPrefs.SetString(PrefBlender, blender);\n        }\n        EditorPrefs.SetString(PrefLast, script);\n        lock (output) output.Clear();\n        var psi = new ProcessStartInfo(blender,\n            $"-b --factory-startup --python \\"{script}\\" -- --out \\"{outDir}\\"")\n        {\n            UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true, CreateNoWindow = true\n        };\n        try\n        {\n            running = new Process { StartInfo = psi };\n            running.OutputDataReceived += (s, e) => { if (e.Data != null) lock (output) output.Add(e.Data); };\n            running.ErrorDataReceived += (s, e) => { if (e.Data != null) lock (output) output.Add(e.Data); };\n            running.Start();\n            running.BeginOutputReadLine();\n            running.BeginErrorReadLine();\n        }\n        catch (Exception ex)\n        {\n            running = null;\n            Debug.LogError($"[Kit Bridge] Could not start Blender ({blender}): {ex.Message}");\n            return;\n        }\n        runningKit = kit; runningOut = outDir; startTime = EditorApplication.timeSinceStartup;\n        Debug.Log($"[Kit Bridge] Building {kit} with {blender}");\n    }\n\n    static void Finish()\n    {\n        EditorUtility.ClearProgressBar();\n        int code = -1;\n        try { code = running.ExitCode; } catch { }\n        running.Dispose(); running = null;\n        string log;\n        lock (output) log = string.Join("\\n", output);\n        bool failed = code != 0 || log.Contains("Traceback") || !log.Contains("Exported");\n        string summary = output.LastOrDefault(l => l.StartsWith("Exported")) ?? "";\n        if (failed)\n            Debug.LogError($"[Kit Bridge] {runningKit} FAILED (exit {code}). Paste this log to Claude:\\n{log}");\n        else\n            Debug.Log($"[Kit Bridge] {runningKit}: {summary}\\n{log}");\n        AssetDatabase.Refresh();          // FBX + palette import; KitSetup makes materials and re-imports\n        string rel = "Assets" + runningOut.Substring(AssetsFull.Length);\n        var folder = AssetDatabase.LoadAssetAtPath<UnityEngine.Object>(rel);\n        if (folder != null) { EditorGUIUtility.PingObject(folder); }\n    }\n\n    // ------------------------------------------------------------------ blender discovery\n    public static string FindBlender()\n    {\n        string pref = EditorPrefs.GetString(PrefBlender, "");\n        if (!string.IsNullOrEmpty(pref) && File.Exists(pref)) return pref;\n        var candidates = new List<string>();\n        foreach (var pf in new[] { Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),\n                                   Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86) })\n        {\n            if (string.IsNullOrEmpty(pf)) continue;\n            string foundation = Path.Combine(pf, "Blender Foundation");\n            if (Directory.Exists(foundation))\n                candidates.AddRange(Directory.GetDirectories(foundation)\n                    .OrderByDescending(d => VersionOf(d))\n                    .Select(d => Path.Combine(d, "blender.exe")));\n            candidates.Add(Path.Combine(pf, "Steam", "steamapps", "common", "Blender", "blender.exe"));\n        }\n        candidates.Add("/Applications/Blender.app/Contents/MacOS/Blender");\n        candidates.Add("/usr/bin/blender");\n        candidates.Add("/snap/bin/blender");\n        foreach (var dir in (Environment.GetEnvironmentVariable("PATH") ?? "").Split(Path.PathSeparator))\n        {\n            if (string.IsNullOrWhiteSpace(dir)) continue;\n            candidates.Add(Path.Combine(dir, "blender.exe"));\n            candidates.Add(Path.Combine(dir, "blender"));\n        }\n        return candidates.FirstOrDefault(File.Exists);\n    }\n\n    static Version VersionOf(string dir)\n    {\n        var m = Regex.Match(Path.GetFileName(dir), @"(\\d+)\\.(\\d+)");\n        return m.Success ? new Version(int.Parse(m.Groups[1].Value), int.Parse(m.Groups[2].Value)) : new Version(0, 0);\n    }\n\n    // ------------------------------------------------------------------ menu\n    [MenuItem("Tools/Kit/Build Kit Script...")]\n    static void BuildFromFile()\n    {\n        string p = EditorUtility.OpenFilePanel("Kit script", Directory.Exists(ScriptsDir) ? ScriptsDir : "", "py");\n        if (string.IsNullOrEmpty(p)) return;\n        if (!IsKitScript(p)) { EditorUtility.DisplayDialog("Kit Bridge", "That file is not a stylized-blender-assets kit script.", "OK"); return; }\n        Offer(p);\n    }\n\n    [MenuItem("Tools/Kit/Rebuild Last Kit")]\n    static void RebuildLast()\n    {\n        string p = EditorPrefs.GetString(PrefLast, "");\n        if (File.Exists(p)) Offer(p);\n        else EditorUtility.DisplayDialog("Kit Bridge", "No kit has been built yet.", "OK");\n    }\n\n    [MenuItem("Tools/Kit/Bridge Settings...")]\n    static void Settings() => KitBridgeSettings.Open();\n}\n\npublic class KitBridgeSettings : EditorWindow\n{\n    public static void Open() => GetWindow<KitBridgeSettings>("Kit Bridge");\n\n    void OnGUI()\n    {\n        EditorGUILayout.LabelField("Blender", EditorStyles.boldLabel);\n        string cur = EditorPrefs.GetString("KitBridge.BlenderPath", "");\n        string found = KitBridge.FindBlender() ?? "(not found)";\n        EditorGUILayout.LabelField("Using", string.IsNullOrEmpty(cur) ? found + "  (auto)" : cur);\n        if (GUILayout.Button("Choose Blender executable..."))\n        {\n            string p = EditorUtility.OpenFilePanel("Locate Blender", "", "");\n            if (!string.IsNullOrEmpty(p)) EditorPrefs.SetString("KitBridge.BlenderPath", p);\n        }\n        if (GUILayout.Button("Use auto-detect")) EditorPrefs.DeleteKey("KitBridge.BlenderPath");\n\n        EditorGUILayout.Space();\n        EditorGUILayout.LabelField("Kit scripts", EditorStyles.boldLabel);\n        EditorGUILayout.LabelField("Kept in", "Assets/KitScripts");\n        KitBridge.WatchDownloads = EditorGUILayout.Toggle("Watch Downloads folder", KitBridge.WatchDownloads);\n        EditorGUILayout.LabelField("Downloads", KitBridge.DownloadsDir);\n        EditorGUILayout.HelpBox("Optional, for kits made in Claude chat: a kit script downloaded there opens a " +\n                                "Build / Ignore dialog. Not needed when Claude Code builds the kits. " +\n                                "Nothing runs without your click.", MessageType.Info);\n    }\n}\n',
    'KitModelPostprocessor': '// Put in any Editor folder (e.g. Assets/Editor/). Runs automatically whenever an FBX is imported or\n// re-exported. ONE copy per project - if an older AtlantisModelPostprocessor.cs exists, delete it,\n// otherwise colliders get added twice.\n//\n// Contract with the Blender kit scripts (stylized-blender-assets):\n//   * Material names: Blender material "Trn_Wood" -> Unity material asset named "Trn_Wood"\n//     (or "Trn_Wood_Toon"). Any name works; Blender ".001" suffixes are ignored.\n//     Set MaterialPrefixes to limit matching to your kit prefixes (empty = match every name).\n//   * Object names:   "..._COL"   -> invisible MeshCollider (renderer removed, materials ignored)\n//                     "..._SOLID" -> visible mesh + MeshCollider\n//   * Static flag on collider objects (they are level geometry).\n// Missing materials are reported once per import in the Console so nothing fails silently.\nusing System.Collections.Generic;\nusing System.IO;\nusing System.Linq;\nusing System.Text.RegularExpressions;\nusing UnityEditor;\nusing UnityEngine;\n\npublic class KitModelPostprocessor : AssetPostprocessor\n{\n    static readonly string[] MaterialPrefixes = { };            // e.g. { "Atl_", "Trn_" }\n    static readonly string[] MaterialSuffixes = { "", "_Toon" };\n    const string ColliderOnlySuffix = "_COL";\n    const string SolidSuffix = "_SOLID";\n    static readonly Regex BlenderDuplicate = new Regex(@"\\.\\d{3}$");\n\n    void OnPostprocessModel(GameObject root)\n    {\n        var missing = new HashSet<string>();\n        var cache = new Dictionary<string, Material>();\n\n        foreach (var t in root.GetComponentsInChildren<Transform>(true))\n        {\n            string name = BlenderDuplicate.Replace(t.name, "");\n            bool colOnly = name.EndsWith(ColliderOnlySuffix);\n            bool solid = name.EndsWith(SolidSuffix);\n\n            // ---- colliders by object-name suffix\n            if (colOnly || solid)\n            {\n                var mf = t.GetComponent<MeshFilter>();\n                if (mf != null && mf.sharedMesh != null)\n                {\n                    var mc = t.gameObject.AddComponent<MeshCollider>();\n                    mc.sharedMesh = mf.sharedMesh;\n                    t.gameObject.isStatic = true;\n                }\n                if (colOnly)\n                {\n                    var mr = t.GetComponent<MeshRenderer>();\n                    if (mr != null) Object.DestroyImmediate(mr, true);\n                    continue;                                       // no materials to swap\n                }\n            }\n\n            // ---- materials: swap embedded FBX materials for the project\'s real ones\n            var r = t.GetComponent<Renderer>();\n            if (r == null) continue;\n            var mats = r.sharedMaterials;\n            bool changed = false;\n            for (int i = 0; i < mats.Length; i++)\n            {\n                if (mats[i] == null) continue;\n                string mname = BlenderDuplicate.Replace(mats[i].name, "");\n                if (MaterialPrefixes.Length > 0 && !MaterialPrefixes.Any(p => mname.StartsWith(p))) continue;\n                if (!cache.TryGetValue(mname, out var found))\n                    cache[mname] = found = FindMaterial(mname);\n                if (found != null) { mats[i] = found; changed = true; }\n                else missing.Add(mname);\n            }\n            if (changed) r.sharedMaterials = mats;\n        }\n\n        if (missing.Count > 0)\n            Debug.LogWarning($"[Kit import] {assetPath}: no Unity material found for " +\n                             $"{string.Join(", ", missing)}. Create material assets with those exact names.");\n    }\n\n    Material FindMaterial(string name)\n    {\n        foreach (var suffix in MaterialSuffixes)\n        {\n            string target = name + suffix;\n            foreach (var guid in AssetDatabase.FindAssets($"{target} t:Material"))\n            {\n                string path = AssetDatabase.GUIDToAssetPath(guid);\n                if (Path.GetFileNameWithoutExtension(path) != target) continue;\n                context.DependsOnSourceAsset(path);       // re-import the model if this material moves/changes\n                var m = AssetDatabase.LoadAssetAtPath<Material>(path);\n                if (m != null) return m;\n            }\n        }\n        return null;\n    }\n}\n',
    'KitSetup': '// Kit Setup - materials + textures for kits exported by stylized-blender-assets scripts.\n// Installed automatically by the kit scripts (any Editor folder works).\n//\n// Every kit export writes "<Kit>_palette.json" next to its FBX files (and, when TEXTURE_STYLE is not\n// "flat", seamless textures in "<folder>/Textures": <Mat>_albedo.png, <Mat>_normal.png, <Mat>_mask.png\n// with R = metallic, G = occlusion, A = smoothness). When the palette is imported or changed this script:\n//   1. sets the texture import settings (albedo sRGB, normal map type, mask linear, repeat wrap),\n//   2. creates/updates the kit\'s materials in "<folder>/Materials" for the active pipeline\n//      (URP Lit, HDRP Lit or Built-in Standard): base map, normal map, metallic/smoothness/occlusion\n//      from the mask, tiling (1 UV unit = 1 m, so tiling = 1 / tile metres), colour when untextured,\n//   3. re-imports the folder\'s FBX files so KitModelPostprocessor swaps the materials in by name.\n// Materials in "<folder>/Materials" belong to the kit and follow the palette on every export.\n// A material with the same name (or name + "_Toon") anywhere else is yours: it is used and never touched.\n// Menu: Tools > Kit > Set Up All Kits\nusing System;\nusing System.Collections.Generic;\nusing System.IO;\nusing UnityEditor;\nusing UnityEngine;\nusing UnityEngine.Rendering;\n\npublic class KitSetup : AssetPostprocessor\n{\n#pragma warning disable 0649   // fields are filled by JsonUtility\n    [Serializable] class PaletteEntry\n    {\n        public string name; public float[] color; public float metallic; public float roughness; public float tile;\n        public string albedo, normal, mask;\n    }\n    [Serializable] class Palette { public string kit; public string style; public PaletteEntry[] materials; }\n#pragma warning restore 0649\n\n    const string Suffix = "_palette.json";\n    static readonly List<string> pending = new List<string>();\n\n    static void OnPostprocessAllAssets(string[] imported, string[] deleted, string[] moved, string[] movedFrom)\n    {\n        foreach (var p in imported)\n            if (p.EndsWith(Suffix, StringComparison.OrdinalIgnoreCase) && !pending.Contains(p))\n                pending.Add(p);\n        if (pending.Count > 0)\n            EditorApplication.delayCall += RunPending;\n    }\n\n    static void RunPending()\n    {\n        if (pending.Count == 0) return;\n        var paths = new List<string>(pending);\n        pending.Clear();\n        foreach (var p in paths) SetUpKit(p);\n    }\n\n    [MenuItem("Tools/Kit/Set Up All Kits")]\n    static void SetUpAll()\n    {\n        int n = 0;\n        foreach (var guid in AssetDatabase.FindAssets("_palette"))\n        {\n            string p = AssetDatabase.GUIDToAssetPath(guid);\n            if (!p.EndsWith(Suffix, StringComparison.OrdinalIgnoreCase)) continue;\n            SetUpKit(p);\n            n++;\n        }\n        if (n == 0)\n            EditorUtility.DisplayDialog("Kit Setup", "No *_palette.json found under Assets.\\n\\n" +\n                "Run a kit script with its export folder inside this Unity project first.", "OK");\n    }\n\n    static void SetUpKit(string palettePath)\n    {\n        Palette pal;\n        try { pal = JsonUtility.FromJson<Palette>(File.ReadAllText(palettePath)); }\n        catch (Exception e) { Debug.LogError($"[Kit Setup] Could not read {palettePath}: {e.Message}"); return; }\n        if (pal == null || pal.materials == null) return;\n\n        string folder = Path.GetDirectoryName(palettePath).Replace(\'\\\\\', \'/\');\n        string texFolder = folder + "/Textures";\n        string matFolder = folder + "/Materials";\n        if (!AssetDatabase.IsValidFolder(matFolder))\n            AssetDatabase.CreateFolder(folder, "Materials");\n\n        // 1. texture import settings (only re-imports textures whose settings change)\n        foreach (var e in pal.materials)\n        {\n            ConfigureTexture(texFolder, e.albedo, TextureImporterType.Default, true);\n            ConfigureTexture(texFolder, e.normal, TextureImporterType.NormalMap, false);\n            ConfigureTexture(texFolder, e.mask, TextureImporterType.Default, false);\n        }\n\n        // 2. materials\n        Shader shader = PipelineShader();\n        int created = 0, updated = 0, userOwned = 0;\n        foreach (var e in pal.materials)\n        {\n            string ownPath = matFolder + "/" + e.name + ".mat";\n            var m = AssetDatabase.LoadAssetAtPath<Material>(ownPath);\n            if (m == null)\n            {\n                if (ExistsElsewhere(e.name, matFolder)) { userOwned++; continue; }\n                m = new Material(shader) { name = e.name };\n                AssetDatabase.CreateAsset(m, ownPath);\n                created++;\n            }\n            else updated++;\n            if (m.shader != shader) m.shader = shader;\n            Apply(m, e, texFolder);\n            EditorUtility.SetDirty(m);\n        }\n        AssetDatabase.SaveAssets();\n\n        // 3. re-import this kit\'s FBX files\n        int fbx = 0;\n        AssetDatabase.StartAssetEditing();\n        try\n        {\n            foreach (var guid in AssetDatabase.FindAssets("t:Model", new[] { folder }))\n            {\n                string p = AssetDatabase.GUIDToAssetPath(guid);\n                if (!p.EndsWith(".fbx", StringComparison.OrdinalIgnoreCase)) continue;\n                if (Path.GetDirectoryName(p).Replace(\'\\\\\', \'/\') != folder) continue;\n                AssetDatabase.ImportAsset(p, ImportAssetOptions.ForceUpdate);\n                fbx++;\n            }\n        }\n        finally { AssetDatabase.StopAssetEditing(); }\n\n        if (Type.GetType("KitModelPostprocessor") == null)\n            Debug.LogWarning("[Kit Setup] KitModelPostprocessor.cs not found in an Editor folder: materials and " +\n                             "colliders will not be hooked up to the FBX files without it.");\n        Debug.Log($"[Kit Setup] {pal.kit} ({pal.style}): {created} material(s) created, {updated} updated, " +\n                  $"{userOwned} of yours kept, {fbx} FBX re-imported - {folder}, shader {shader.name}.");\n    }\n\n    static void ConfigureTexture(string texFolder, string file, TextureImporterType type, bool srgb)\n    {\n        if (string.IsNullOrEmpty(file)) return;\n        string path = texFolder + "/" + file;\n        var ti = AssetImporter.GetAtPath(path) as TextureImporter;\n        if (ti == null) return;\n        bool dirty = false;\n        if (ti.textureType != type) { ti.textureType = type; dirty = true; }\n        if (type != TextureImporterType.NormalMap && ti.sRGBTexture != srgb) { ti.sRGBTexture = srgb; dirty = true; }\n        if (ti.wrapMode != TextureWrapMode.Repeat) { ti.wrapMode = TextureWrapMode.Repeat; dirty = true; }\n        if (!ti.mipmapEnabled) { ti.mipmapEnabled = true; dirty = true; }\n        if (dirty) ti.SaveAndReimport();\n    }\n\n    static Texture2D Tex(string texFolder, string file) =>\n        string.IsNullOrEmpty(file) ? null : AssetDatabase.LoadAssetAtPath<Texture2D>(texFolder + "/" + file);\n\n    static bool ExistsElsewhere(string name, string matFolder)\n    {\n        foreach (var target in new[] { name, name + "_Toon" })\n            foreach (var guid in AssetDatabase.FindAssets(target + " t:Material"))\n            {\n                string p = AssetDatabase.GUIDToAssetPath(guid);\n                if (Path.GetFileNameWithoutExtension(p) == target &&\n                    Path.GetDirectoryName(p).Replace(\'\\\\\', \'/\') != matFolder)\n                    return true;\n            }\n        return false;\n    }\n\n    static Shader PipelineShader()\n    {\n        var rp = GraphicsSettings.currentRenderPipeline;\n        string type = rp == null ? "" : rp.GetType().Name;\n        string want = type.Contains("Universal") ? "Universal Render Pipeline/Lit"\n                    : type.Contains("HD") ? "HDRP/Lit" : "Standard";\n        return Shader.Find(want) ?? Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("HDRP/Lit") ?? Shader.Find("Standard");\n    }\n\n    static void SetTex(Material m, string prop, Texture2D t)\n    {\n        if (m.HasProperty(prop)) m.SetTexture(prop, t);\n    }\n\n    static void Keyword(Material m, string kw, bool on)\n    {\n        if (on) m.EnableKeyword(kw); else m.DisableKeyword(kw);\n    }\n\n    static void Apply(Material m, PaletteEntry e, string texFolder)\n    {\n        var albedo = Tex(texFolder, e.albedo);\n        var normal = Tex(texFolder, e.normal);\n        var mask = Tex(texFolder, e.mask);\n        // Blender colours are linear; Unity colour properties are authored in sRGB.\n        var c = new Color(e.color[0], e.color[1], e.color[2], 1f).gamma;\n        var tint = albedo != null ? Color.white : c;            // albedo already carries the colour\n        float smooth = Mathf.Clamp01(1f - e.roughness);\n        float tiling = e.tile > 0f ? 1f / e.tile : 1f;           // UVs are in metres\n        var scale = new Vector2(tiling, tiling);\n\n        // colour\n        if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", tint);        // URP / HDRP\n        if (m.HasProperty("_Color")) m.SetColor("_Color", tint);                // Built-in\n        SetTex(m, "_BaseMap", albedo);                                          // URP\n        SetTex(m, "_MainTex", albedo);                                          // Built-in (URP mirrors it)\n        SetTex(m, "_BaseColorMap", albedo);                                     // HDRP\n        foreach (var p in new[] { "_BaseMap", "_MainTex", "_BaseColorMap" })\n            if (m.HasProperty(p)) m.SetTextureScale(p, scale);\n\n        // normal\n        SetTex(m, "_BumpMap", normal);                                          // URP / Built-in\n        SetTex(m, "_NormalMap", normal);                                        // HDRP\n        if (m.HasProperty("_BumpScale")) m.SetFloat("_BumpScale", 1f);\n        Keyword(m, "_NORMALMAP", normal != null);\n        Keyword(m, "_NORMALMAP_TANGENT_SPACE", normal != null);\n\n        // metallic / smoothness / occlusion\n        if (m.HasProperty("_Metallic")) m.SetFloat("_Metallic", e.metallic);\n        if (mask != null)\n        {\n            SetTex(m, "_MetallicGlossMap", mask);                               // URP / Built-in: R metal, A smooth\n            SetTex(m, "_OcclusionMap", mask);                                   // URP / Built-in read G\n            SetTex(m, "_MaskMap", mask);                                        // HDRP: R metal, G AO, A smooth\n            if (m.HasProperty("_SmoothnessTextureChannel")) m.SetFloat("_SmoothnessTextureChannel", 0f);  // metallic alpha\n            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", 1f);    // URP: map alpha x this\n            if (m.HasProperty("_GlossMapScale")) m.SetFloat("_GlossMapScale", 1f);\n            if (m.HasProperty("_OcclusionStrength")) m.SetFloat("_OcclusionStrength", 1f);\n            if (m.HasProperty("_Glossiness")) m.SetFloat("_Glossiness", smooth);\n        }\n        else\n        {\n            SetTex(m, "_MetallicGlossMap", null); SetTex(m, "_OcclusionMap", null); SetTex(m, "_MaskMap", null);\n            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", smooth);\n            if (m.HasProperty("_Glossiness")) m.SetFloat("_Glossiness", smooth);\n        }\n        Keyword(m, "_METALLICSPECGLOSSMAP", mask != null);                      // URP\n        Keyword(m, "_METALLICGLOSSMAP", mask != null);                          // Built-in\n        Keyword(m, "_OCCLUSIONMAP", mask != null);\n        Keyword(m, "_MASKMAP", mask != null);                                   // HDRP\n        Keyword(m, "_SMOOTHNESS_TEXTURE_ALBEDO_CHANNEL_A", false);\n    }\n}\n',
}

# ======================================================================
# STYLIZED KIT LIB  -  generic Blender building code for game assets
# Blender 3.x / 4.x / 5.x. scripts/assemble.py pastes this between the CONFIG block and the
# piece code, so the user always gets ONE self-contained script.
#
# Run it any of these ways:
#   * Blender UI: Scripting tab > Open > Run Script
#   * blender --python my_kit.py                          (opens Blender with the scene built)
#   * blender --background --python my_kit.py            (headless: just export)
#   * blender -b --python my_kit.py -- --out "D:/Game/Assets/Models/Train" --only Seat_Double
# Script args after "--":  --out DIR   --no-export   --only Name1,Name2
# ======================================================================
import bpy, bmesh, os, sys, random
from math import pi, sin, cos, radians, degrees, atan2, sqrt
from mathutils import Matrix, Vector

# ---------------------------------------------------------------- config (set in the CONFIG block)
EXPORT_DIR = globals().get("EXPORT_DIR", "")          # "" = <KIT_NAME>_FBX next to the .blend
KIT_NAME = globals().get("KIT_NAME", "Kit")
TEXTURE_STYLE = globals().get("TEXTURE_STYLE", "flat")  # "flat" | "toon" | "painted" | "pbr"
TEXTURE_RES = globals().get("TEXTURE_RES", 1024)       # pixels per tile (power of two)
TEX_PATHS = {}                                          # material name -> {"albedo"|"normal"|"mask": path}
PREVIEW = bool(globals().get("__KIT_PREVIEW__", False) or globals().get("__ATLANTIS_PREVIEW__", False))
PREVIEW_REGISTRY = []

def cli_args():
    """Arguments after '--' on the Blender command line."""
    argv = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else []
    opts = {"out": "", "export": True, "only": None}
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--out" and i + 1 < len(argv):
            opts["out"] = argv[i + 1]; i += 1
        elif a == "--no-export":
            opts["export"] = False
        elif a == "--only" and i + 1 < len(argv):
            opts["only"] = set(argv[i + 1].split(",")); i += 1
        i += 1
    return opts

# ---------------------------------------------------------------- palette / materials
# A palette is the material contract with the engine: Blender material NAME == engine material name.
# Each entry: (name, linear RGB, metallic, roughness[, {"tex": recipe, "tile": metres, ...}]).
# Slot index = position in the list. The optional 5th element drives texture generation
# (kit_textures.py recipes: wood, velvet/fabric, brushed/brass, painted_metal, plaster/paint, leather,
# marble, stone, plain). "tile" = how many metres one texture repeat covers (UVs are in metres).
PALETTE = [("Kit_Main", (0.62, 0.62, 0.60), 0.0, 0.7),
           ("Kit_Trim", (0.30, 0.30, 0.32), 0.0, 0.7),
           ("Kit_Accent", (0.95, 0.70, 0.25), 1.0, 0.3),
           ("Kit_Natural", (0.42, 0.50, 0.40), 0.0, 0.8)]
SLOT_MAIN, SLOT_TRIM, SLOT_ACCENT, SLOT_NATURAL = 0, 1, 2, 3

def set_palette(entries):
    """Replace the palette. Returns range(len) so you can unpack slot constants:
    WOOD, BRASS, CLOTH = set_palette([("Trn_Wood", ...), ("Trn_Brass", ...), ("Trn_Cloth", ...)])"""
    global PALETTE
    PALETTE = list(entries)
    return range(len(PALETTE))

def reset_scene():
    if bpy.context.object and bpy.context.object.mode != 'OBJECT':
        bpy.ops.object.mode_set(mode='OBJECT')
    bpy.ops.object.select_all(action='SELECT')
    bpy.ops.object.delete()
    for block in (bpy.data.meshes, bpy.data.materials):
        for item in list(block):
            if item.users == 0:
                block.remove(item)

def mat(name, color, metallic=0.0, rough=0.7):
    m = bpy.data.materials.get(name)
    if m is not None:
        return m
    m = bpy.data.materials.new(name)
    if bpy.app.version < (5, 0, 0):          # 5.x: materials always use nodes (setting it is deprecated)
        m.use_nodes = True
    nt = m.node_tree
    b = nt.nodes.get("Principled BSDF")
    b.inputs["Base Color"].default_value = (*color, 1)
    b.inputs["Metallic"].default_value = metallic
    b.inputs["Roughness"].default_value = rough
    m.diffuse_color = (*color, 1)
    tex = TEX_PATHS.get(name)
    if tex:
        spec = next((e[4] for e in PALETTE if e[0] == name and len(e) > 4), {})
        k = 1.0 / spec.get("tile", 1.0)
        coord = nt.nodes.new("ShaderNodeTexCoord"); coord.location = (-900, 0)
        mp = nt.nodes.new("ShaderNodeMapping"); mp.location = (-700, 0)
        mp.inputs["Scale"].default_value = (k, k, 1.0)
        nt.links.new(coord.outputs["UV"], mp.inputs["Vector"])
        def img_node(key, y, noncolor):
            n = nt.nodes.new("ShaderNodeTexImage"); n.location = (-450, y)
            n.image = bpy.data.images.load(tex[key], check_existing=True)
            if noncolor:
                n.image.colorspace_settings.name = "Non-Color"
            nt.links.new(mp.outputs["Vector"], n.inputs["Vector"])
            return n
        alb = img_node("albedo", 300, False)
        nt.links.new(alb.outputs["Color"], b.inputs["Base Color"])
        msk = img_node("mask", 0, True)
        inv = nt.nodes.new("ShaderNodeMath"); inv.operation = 'SUBTRACT'; inv.location = (-200, 0)
        inv.inputs[0].default_value = 1.0
        nt.links.new(msk.outputs["Alpha"], inv.inputs[1])           # roughness = 1 - smoothness
        nt.links.new(inv.outputs["Value"], b.inputs["Roughness"])
        nrm = img_node("normal", -300, True)
        nm = nt.nodes.new("ShaderNodeNormalMap"); nm.location = (-200, -300)
        nt.links.new(nrm.outputs["Color"], nm.inputs["Color"])
        nt.links.new(nm.outputs["Normal"], b.inputs["Normal"])
    return m

def generate_textures(out):
    """Write seamless texture sets for every palette entry into <out>/Textures (TEXTURE_STYLE != flat)."""
    TEX_PATHS.clear()
    if TEXTURE_STYLE == "flat" or "make_texture_set" not in globals():
        return
    import numpy as np
    folder = os.path.join(out, "Textures")
    os.makedirs(folder, exist_ok=True)
    for e in PALETTE:
        maps = make_texture_set(e, TEXTURE_STYLE, n=TEXTURE_RES)
        TEX_PATHS[e[0]] = {}
        for key, arr in maps.items():
            nm = f"{e[0]}_{key}"
            img = bpy.data.images.get(nm) or bpy.data.images.new(nm, TEXTURE_RES, TEXTURE_RES, alpha=True)
            if key != "albedo":
                img.colorspace_settings.name = "Non-Color"
            img.pixels.foreach_set(np.ascontiguousarray(arr, dtype=np.float32).ravel())
            path = os.path.join(folder, nm + ".png")
            img.filepath_raw = path
            img.file_format = 'PNG'
            img.save()
            TEX_PATHS[e[0]][key] = path
    print("Textures: %s style, %d materials -> %s" % (TEXTURE_STYLE, len(TEX_PATHS), folder))

def palette_materials():
    return [mat(*e[:4]) for e in PALETTE]

def collider_material():
    return mat("Kit_Collider", (1.0, 0.0, 1.0))

# ---------------------------------------------------------------- blender helpers
def activate(obj):
    bpy.ops.object.select_all(action='DESELECT')
    obj.select_set(True)
    bpy.context.view_layer.objects.active = obj

def shade(obj, angle):
    activate(obj)
    try:
        bpy.ops.object.shade_smooth_by_angle(angle=radians(angle))        # 4.1+
    except (AttributeError, RuntimeError):
        bpy.ops.object.shade_smooth()
        if hasattr(obj.data, "use_auto_smooth"):                         # <= 4.0
            obj.data.use_auto_smooth = True
            obj.data.auto_smooth_angle = radians(angle)

# ---------------------------------------------------------------- mesh builder
class MB:
    """Accumulates verts/faces (one material slot per face) into a single mesh."""
    def __init__(self):
        self.v, self.f, self.m = [], [], []
        self.pid, self.npieces = [], 0      # piece id per face (used by the z-fighting check)

    def add(self, verts, faces, slot=0):
        o = len(self.v)
        self.v += [tuple(p) for p in verts]
        self.f += [[i + o for i in face] for face in faces]
        self.m += [slot] * len(faces)
        self.pid += [self.npieces] * len(faces)
        self.npieces += 1

    def merge(self, other, mat4):
        o = len(self.v)
        self.v += [tuple(mat4 @ Vector(p)) for p in other.v]
        self.f += [[i + o for i in face] for face in other.f]
        self.m += other.m
        self.pid += [self.npieces + p for p in other.pid]
        self.npieces += other.npieces

    def merge_mirror_x(self, other):
        """Add `other` mirrored across x = 0 (faces reversed so normals stay outward)."""
        o = len(self.v)
        self.v += [(-x, y, z) for x, y, z in other.v]
        self.f += [[i + o for i in reversed(face)] for face in other.f]
        self.m += other.m
        self.pid += [self.npieces + p for p in other.pid]
        self.npieces += other.npieces

    def box(self, center, size, slot=0, rot=None):
        hx, hy, hz = (s / 2 for s in size)
        pts = [Vector((x * hx, y * hy, z * hz)) for z in (-1, 1)
               for (x, y) in ((-1, -1), (1, -1), (1, 1), (-1, 1))]
        if rot is not None:
            pts = [rot @ p for p in pts]
        c = Vector(center)
        self.add([p + c for p in pts], [[0, 3, 2, 1], [4, 5, 6, 7], [0, 1, 5, 4],
                                       [1, 2, 6, 5], [2, 3, 7, 6], [3, 0, 4, 7]], slot)

    def rect(self, x0, x1, y0, y1, z0, z1, slot=0):
        """Axis-aligned box from extents (skips degenerate boxes)."""
        if x1 - x0 > 1e-4 and y1 - y0 > 1e-4 and z1 - z0 > 1e-4:
            self.box(((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2), (x1 - x0, y1 - y0, z1 - z0), slot)

    def extrude(self, profile, axis, a0, a1, slot=0):
        """Closed 2D profile extruded along an axis. axis 'y': (x, z) points; axis 'x': (y, z) points."""
        n = len(profile)
        verts = ([(p, a, q) for a in (a0, a1) for p, q in profile] if axis == 'y'
                 else [(a, p, q) for a in (a0, a1) for p, q in profile])
        faces = [list(range(n)), list(reversed(range(n, 2 * n)))]
        faces += [[i, (i + 1) % n, n + (i + 1) % n, n + i] for i in range(n)]
        self.add(verts, faces, slot)

    def lathe(self, profile, segs=32, slot=0, cap_bottom=True, cap_top=True, closed=False,
              center=(0, 0, 0), mat3=None):
        """Spin (radius, z) points around Z. closed=True joins last->first (rings, annuli).
        mat3 rotates the result before it is moved to center (e.g. Rotation(90,'Y') = lying along X)."""
        cx, cy, cz = center
        verts, faces = [], []
        for r, z in profile:
            for j in range(segs):
                a = 2 * pi * j / segs
                p = Vector((r * cos(a), r * sin(a), z))
                if mat3:
                    p = mat3 @ p
                verts.append((p.x + cx, p.y + cy, p.z + cz))
        n = len(profile)
        for i in range(n if closed else n - 1):
            i1 = (i + 1) % n
            for j in range(segs):
                j1 = (j + 1) % segs
                faces.append([i * segs + j, i * segs + j1, i1 * segs + j1, i1 * segs + j])
        if not closed:
            if cap_bottom:
                faces.append(list(reversed(range(segs))))
            if cap_top:
                faces.append([(n - 1) * segs + j for j in range(segs)])
        self.add(verts, faces, slot)

    def cylinder(self, r, z0, z1, slot=0, segs=24, center=(0, 0, 0), mat3=None):
        self.lathe([(r, z0), (r, z1)], segs=segs, slot=slot, center=center, mat3=mat3)

    def annulus(self, r_in, r_out, z0, z1, slot=0, segs=96, center=(0, 0, 0)):
        self.lathe([(max(r_in, 0.001), z0), (r_out, z0), (r_out, z1), (max(r_in, 0.001), z1)],
                   segs=segs, slot=slot, closed=True, center=center)

    def sphere(self, radius, center, slot=0, segs=24, rings=12):
        prof = [(radius * sin(t), -radius * cos(t)) for t in [pi * k / rings for k in range(1, rings)]]
        self.lathe(prof, segs=segs, slot=slot, center=center)

    def build(self, name, mats, bevel=0.0, smooth_angle=32, uv=True):
        """uv=True: world-scale box mapping (1 UV unit = 1 m, projected along each face's main axis),
        so tiling textures line up across modules on a metre grid."""
        mesh = bpy.data.meshes.new(name)
        mesh.from_pydata(self.v, [], self.f)
        mesh.update()
        used = sorted(set(self.m))                 # only the slots this mesh uses -> no empty
        remap = {s: i for i, s in enumerate(used)}   # material slots / submeshes in the engine
        for s in used:
            mesh.materials.append(mats[s] if s < len(mats) else mats[-1])
        for poly, s in zip(mesh.polygons, self.m):
            poly.material_index = remap[s]
        if uv:
            uvl = mesh.uv_layers.new(name="UVMap")
            verts = mesh.vertices
            for poly in mesh.polygons:
                nx, ny, nz = (abs(c) for c in poly.normal)
                for li in poly.loop_indices:
                    co = verts[mesh.loops[li].vertex_index].co
                    if nz >= nx and nz >= ny:
                        uvl.data[li].uv = (co.x, co.y)
                    elif nx >= ny:
                        uvl.data[li].uv = (co.y, co.z)
                    else:
                        uvl.data[li].uv = (co.x, co.z)
        obj = bpy.data.objects.new(name, mesh)
        bpy.context.collection.objects.link(obj)
        activate(obj)
        bpy.ops.object.mode_set(mode='EDIT')
        bpy.ops.mesh.select_all(action='SELECT')
        # NO merge-by-distance: touching blocks must stay separate closed pieces (see pitfalls.md).
        bpy.ops.mesh.normals_make_consistent(inside=False)
        bpy.ops.object.mode_set(mode='OBJECT')
        if bevel:
            mod = obj.modifiers.new("Bevel", 'BEVEL')
            mod.width = bevel
            mod.segments = 2
            mod.limit_method = 'ANGLE'
            mod.angle_limit = radians(50)
            bpy.ops.object.modifier_apply(modifier=mod.name)
        shade(obj, smooth_angle)
        return obj

def place(kh, kv, x, y, z, yaw=0.0):
    """Transform for an upright sub-piece: kh = width scale, kv = height scale."""
    return (Matrix.Translation((x, y, z)) @ Matrix.Rotation(radians(yaw), 4, 'Z') @
            Matrix.Diagonal((kh, kh, kv, 1.0)))

def place_lying(kh, klen, x, y, z, yaw=0.0):
    """Transform for a sub-piece lying along X: klen scales length, kh thickness."""
    return (Matrix.Translation((x, y, z)) @ Matrix.Rotation(radians(yaw), 4, 'Z') @
            Matrix.Diagonal((klen, kh, kh, 1.0)))

def sx(s, a, b):
    """Mirror an x interval [a, b] written for the +x side to side s (+1 / -1). Works for y too."""
    return (a, b) if s > 0 else (-b, -a)

# ---------------------------------------------------------------- organic shapes
def rock(mb, r, center, size, slot=SLOT_NATURAL, subdiv=2):
    """Faceted boulder: jittered icosphere, flattened base."""
    bm = bmesh.new()
    try:
        bmesh.ops.create_icosphere(bm, subdivisions=subdiv, radius=1.0)
    except TypeError:
        bmesh.ops.create_icosphere(bm, subdivisions=subdiv, diameter=1.0)
    verts = []
    for v in bm.verts:
        k = r.uniform(0.8, 1.15)
        p = Vector((v.co.x * size[0] * k, v.co.y * size[1] * k, max(v.co.z * size[2] * k, -size[2] * 0.3)))
        verts.append(p + Vector(center) + Vector((0, 0, size[2] * 0.25)))
    faces = [[v.index for v in f.verts] for f in bm.faces]
    bm.free()
    mb.add(verts, faces, slot)

def arc_wall(mb, r_in, r_out, z0, z1, a0, a1, slot=0, seg_len=1.5):
    """Curved wall/beam segment between angles a0..a1 (radians)."""
    segs = max(2, int(abs(a1 - a0) * r_out / seg_len))
    verts, faces = [], []
    for k in range(segs + 1):
        a = a0 + (a1 - a0) * k / segs
        for r_, z_ in ((r_in, z0), (r_out, z0), (r_out, z1), (r_in, z1)):
            verts.append((r_ * cos(a), r_ * sin(a), z_))
    for k in range(segs):
        for e in range(4):
            e1 = (e + 1) % 4
            faces.append([k * 4 + e, k * 4 + e1, (k + 1) * 4 + e1, (k + 1) * 4 + e])
    faces.append([3, 2, 1, 0])
    faces.append([segs * 4 + i for i in range(4)])
    mb.add(verts, faces, slot)

# ---------------------------------------------------------------- architecture
def wall(mb, axis, c, a0, a1, z0, height, thick, openings=(), slot=0):
    """Axis-aligned wall from boxes, with rectangular openings (no booleans).
    axis 'x': runs along X at y = c.  axis 'y': runs along Y at x = c.
    openings: (center, width, bottom, top) with bottom/top RELATIVE to z0."""
    def piece(b0, b1, za, zb):
        if b1 - b0 < 1e-4 or zb - za < 1e-4:
            return
        m, L = (b0 + b1) / 2, b1 - b0
        if axis == 'x':
            mb.box((m, c, (za + zb) / 2), (L, thick, zb - za), slot)
        else:
            mb.box((c, m, (za + zb) / 2), (thick, L, zb - za), slot)
    cur = a0
    for oc, w, b, t in sorted(openings):
        l, r_ = oc - w / 2, oc + w / 2
        piece(cur, l, z0, z0 + height)
        if b > 0:
            piece(l, r_, z0, z0 + min(b, height))
        if t < height:
            piece(l, r_, z0 + t, z0 + height)
        cur = r_
    piece(cur, a1, z0, z0 + height)

def frame_opening(mb, axis, face, inward, center, width, bottom, top, slot,
                  jamb=(0.08, 0.06), head=(0.10, 0.07), sill=(0.08, 0.08), sill_drop=0.08):
    """Trim around an opening on ONE wall face. face = coordinate of that face, inward = +1/-1 the
    direction the trim projects. (width, depth) per part; depths differ on purpose (no z-fighting).
    bottom/top are absolute z. sill=None for doors."""
    def r(a0, a1, d, z0, z1):
        f0, f1 = sorted((face, face + inward * d))
        if axis == 'y':
            mb.rect(f0, f1, a0, a1, z0, z1, slot)
        else:
            mb.rect(a0, a1, f0, f1, z0, z1, slot)
    l, rr = center - width / 2, center + width / 2
    jw, jd = jamb
    hw, hd = head
    r(l - jw, l, jd, bottom, top)
    r(rr, rr + jw, jd, bottom, top)
    r(l - jw, rr + jw, hd, top, top + hw)
    if sill:
        sw, sd = sill
        r(l - jw - 0.02, rr + jw + 0.02, sd, bottom - sill_drop, bottom)

def band(mb, axis, face, inward, a0, a1, z0, z1, depth, slot, gaps=()):
    """Horizontal trim band on one wall face (baseboard, dado, cornice, stripe). gaps: [(a0, a1)]."""
    f0, f1 = sorted((face, face + inward * depth))
    cur = a0
    for g0, g1 in sorted(gaps) + [(a1, a1)]:
        if g0 > cur:
            if axis == 'y':
                mb.rect(f0, f1, cur, min(g0, a1), z0, z1, slot)
            else:
                mb.rect(cur, min(g0, a1), f0, f1, z0, z1, slot)
        cur = max(cur, g1)

def block_walls(mb, x0, x1, y0, y1, z0, h, ops, thick=0.3, slot=0):
    """Four walls of a rectangular block. ops: {'front'|'back'|'left'|'right': [openings]}.
    front/back run along X (positions in X), left/right along Y. Side walls fit between."""
    wall(mb, 'x', y0 + thick / 2, x0, x1, z0, h, thick, ops.get('front', ()), slot)
    wall(mb, 'x', y1 - thick / 2, x0, x1, z0, h, thick, ops.get('back', ()), slot)
    wall(mb, 'y', x0 + thick / 2, y0 + thick, y1 - thick, z0, h, thick, ops.get('left', ()), slot)
    wall(mb, 'y', x1 - thick / 2, y0 + thick, y1 - thick, z0, h, thick, ops.get('right', ()), slot)

def slab_with_hole(mb, x0, x1, y0, y1, z0, z1, hole=None, slot=0, rim_slot=None):
    if not hole:
        mb.rect(x0, x1, y0, y1, z0, z1, slot)
        return
    hx0, hx1, hy0, hy1 = hole
    mb.rect(x0, x1, y0, hy0, z0, z1, slot)
    mb.rect(x0, x1, hy1, y1, z0, z1, slot)
    mb.rect(x0, hx0, hy0, hy1, z0, z1, slot)
    mb.rect(hx1, x1, hy0, hy1, z0, z1, slot)
    if rim_slot is not None:
        for (a, b_, c_, d) in ((hx0, hx1, hy0 - 0.15, hy0), (hx0, hx1, hy1, hy1 + 0.15)):
            mb.rect(a, b_, c_, d, z1, z1 + 0.04, rim_slot)

def runs(states):
    """Index ranges of consecutive 'ok' entries (length >= 2) - e.g. beams between intact posts."""
    out, start = [], None
    for i, s in enumerate(list(states) + ['x']):
        if s == 'ok' and start is None:
            start = i
        elif s != 'ok' and start is not None:
            if i - start >= 2:
                out.append((start, i - 1))
            start = None
    return out

# ---------------------------------------------------------------- asset container
class Asset:
    """One exported FBX (root empty named `name`). Mesh buckets:
      S   -> "Structure_SOLID"  visible + mesh collider (walls, floors, furniture bodies)
      P   -> "Props_SOLID"      visible + mesh collider (loose clutter)
      D   -> "Detail"           visible, NO collider (fine/round detail: columns, lamps, foliage)
      COL -> "Detail_COL"       invisible simple collider proxy for D
    Empties: anchors -> "Anchors/Anchor_##" (grapple points, spawn points, sockets...)."""
    DETAIL_NAME = "Detail"
    ANCHOR_GROUP = "Anchors"

    def __init__(self, name, seed=1):
        self.name = name
        self.rng = random.Random(seed)
        self.S, self.D, self.COL, self.P = MB(), MB(), MB(), MB()
        self.anchors = []
        self.n = 0

    @property
    def C(self):              # legacy alias (Fathom scripts call the detail bucket C)
        return self.D

    def state(self, p_broken, p_missing, protect=False):
        """Seeded damage state: 'ok' | 'broken' | 'missing'."""
        if protect:
            return 'ok'
        r = self.rng.random()
        return 'missing' if r < p_missing else 'broken' if r < p_missing + p_broken else 'ok'

    def finish(self, anchors=False, anchor_group=None):
        if PREVIEW:
            PREVIEW_REGISTRY.append(self)
            return None, []
        mats = palette_materials()
        bpy.ops.object.empty_add(type='PLAIN_AXES', location=(0, 0, 0))
        root = bpy.context.object
        root.name = self.name
        objs = [root]
        if self.S.v:
            objs.append(self.S.build("Structure_SOLID", mats, bevel=0.0, smooth_angle=30))   # no bevel: blocks abut
        if self.D.v:
            objs.append(self.D.build(self.DETAIL_NAME, mats, bevel=0.02))
            if self.COL.v:
                col = self.COL.build(self.DETAIL_NAME + "_COL", [collider_material()], uv=False, smooth_angle=0)
                col.display_type = 'WIRE'
                col.hide_render = True
                objs.append(col)
        if self.P.v:
            objs.append(self.P.build("Props_SOLID", mats, bevel=0.0))
        for o in objs[1:]:
            o.parent = root
        if anchors and self.anchors:
            bpy.ops.object.empty_add(type='PLAIN_AXES', location=(0, 0, 0))
            ar = bpy.context.object
            ar.name = anchor_group or self.ANCHOR_GROUP
            ar.parent = root
            objs.append(ar)
            for i, (x, y, z) in enumerate(self.anchors):
                bpy.ops.object.empty_add(type='SPHERE', radius=0.5, location=(x, y, z))
                e = bpy.context.object
                e.name = f"Anchor_{i:02d}"
                e.parent = ar
                objs.append(e)
        return root, objs

# ---------------------------------------------------------------- export + run
def export_dir(custom=""):
    if custom or EXPORT_DIR:
        return os.path.expanduser(custom or EXPORT_DIR)
    folder = f"{KIT_NAME}_FBX"
    if bpy.data.filepath:
        return os.path.join(os.path.dirname(bpy.data.filepath), folder)
    return os.path.join(os.path.expanduser("~"), folder)

def export_fbx(root, objs, out):
    """Unity-ready FBX: 1 m = 1 unit, Y up, no -90 X rotation, scale 1 on import."""
    os.makedirs(out, exist_ok=True)
    bpy.ops.object.select_all(action='DESELECT')
    for o in objs:
        o.select_set(True)
    bpy.context.view_layer.objects.active = root
    bpy.ops.export_scene.fbx(
        filepath=os.path.join(out, root.name + ".fbx"),
        use_selection=True, object_types={'MESH', 'EMPTY'},
        apply_scale_options='FBX_SCALE_ALL', apply_unit_scale=True,
        axis_forward='-Z', axis_up='Y', bake_space_transform=True,
        mesh_smooth_type='FACE', add_leaf_bones=False, bake_anim=False)

def export_palette(out):
    """<KIT_NAME>_palette.json next to the FBX files: lets the engine-side setup create the materials."""
    import json
    os.makedirs(out, exist_ok=True)
    mats = []
    for e in PALETTE:
        n, c, m, r = e[:4]
        spec = e[4] if len(e) > 4 else {}
        d = {"name": n, "color": list(c), "metallic": m, "roughness": r, "tile": spec.get("tile", 1.0)}
        if n in TEX_PATHS:
            d["albedo"] = n + "_albedo.png"; d["normal"] = n + "_normal.png"; d["mask"] = n + "_mask.png"
        mats.append(d)
    data = {"kit": KIT_NAME, "style": TEXTURE_STYLE, "materials": mats}
    with open(os.path.join(out, f"{KIT_NAME}_palette.json"), "w") as f:
        json.dump(data, f, indent=2)

# ---------------------------------------------------------------- Unity tools auto-install
UNITY_TOOLS = globals().get("UNITY_TOOLS", {})        # {ClassName: C# source}, embedded by assemble.py

def find_unity_project(path):
    """Walk up from the export folder to the folder holding Assets/ + ProjectSettings/."""
    p = os.path.abspath(path)
    while True:
        if os.path.isdir(os.path.join(p, "Assets")) and os.path.isdir(os.path.join(p, "ProjectSettings")):
            return p
        parent = os.path.dirname(p)
        if parent == p:
            return None
        p = parent

def install_unity_tools(out):
    """Install/update the embedded editor scripts. A file already declaring the same class (e.g. one the
    user copied by hand) is updated IN PLACE, so there are never duplicate classes."""
    import re
    if not UNITY_TOOLS:
        return
    proj = find_unity_project(out)
    if not proj:
        print("Unity tools: export folder is not inside a Unity project - not installed")
        return
    assets = os.path.join(proj, "Assets")
    where, legacy = {}, []
    for root, dirs, files in os.walk(assets):
        for fn in files:
            if not fn.endswith(".cs"):
                continue
            fp = os.path.join(root, fn)
            try:
                with open(fp, encoding="utf-8", errors="ignore") as f:
                    txt = f.read()
            except OSError:
                continue
            for cls in UNITY_TOOLS:
                if cls not in where and re.search(r"\b(class|struct)\s+%s\b" % cls, txt):
                    where[cls] = fp
            if re.search(r"\bclass\s+AtlantisModelPostprocessor\b", txt):
                legacy.append(fp)
    changed = []
    for cls, src in UNITY_TOOLS.items():
        path = where.get(cls) or os.path.join(assets, "KitTools", "Editor", cls + ".cs")
        try:
            with open(path, encoding="utf-8") as f:
                if f.read() == src:
                    continue
        except OSError:
            pass
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(src)
        changed.append(os.path.relpath(path, proj))
    print("Unity tools: " + (("updated " + ", ".join(changed)) if changed else "up to date"))
    for fp in legacy:
        print("Unity tools: WARNING old %s also adds colliders - delete it to avoid double colliders" % fp)

def run(builders, export=True, out_dir="", spacing=None):
    """Build + export each asset in turn (one FBX each), then lay them out in a row for viewing."""
    reset_scene()
    opts = cli_args()
    if PREVIEW:
        return [b() for b in builders]
    export = export and opts["export"]
    out = export_dir(opts["out"] or out_dir)
    built = []
    import tempfile
    generate_textures(out if export else os.path.join(tempfile.gettempdir(), KIT_NAME + "_textures"))
    if export:
        export_palette(out)
        install_unity_tools(out)
    for b in builders:
        root, objs = b()
        if export and (not opts["only"] or root.name in opts["only"]):
            export_fbx(root, objs, out)
        for o in objs[1:]:                      # free the short child names for the next asset
            o.name = f"{root.name}_{o.name}"
            if o.data is not None:
                o.data.name = o.name
        built.append((root, objs))
    x = 0.0
    for i, (root, objs) in enumerate(built):
        if i:
            x += spacing or 30.0
        root.location.x = x
    bpy.ops.object.light_add(type='SUN', location=(0, 0, 50), rotation=(radians(40), 0, radians(30)))
    bpy.context.object.data.energy = 3
    print("Built:", ", ".join(r.name for r, _ in built))
    n = sum(1 for r, _ in built if not opts["only"] or r.name in opts["only"])
    print(("Exported %d FBX -> %s" % (n, out)) if export else "Export skipped (--no-export)")
    return built


# ======================================================================
# KIT TEXTURES  -  seamless procedural textures for palette materials (numpy only; runs inside Blender)
# A palette entry may carry a 5th element: {"tex": recipe, "tile": metres, ...recipe params}.
# Styles (TEXTURE_STYLE in CONFIG): "flat" (no textures), "toon", "painted", "pbr".
# Every map tiles seamlessly: noise is built in the frequency domain (periodic by construction) and
# every stripe/plank pattern uses whole-number repeats per tile.
# Output per material: <name>_albedo.png (sRGB), <name>_normal.png (OpenGL / Unity), <name>_mask.png
# (R = metallic, G = AO-ish cavity, A = smoothness -> URP Lit "Metallic Alpha" smoothness).
# ======================================================================
import numpy as _np

TEXTURE_STYLES = {
    # detail: pattern strength, fine: small-scale detail, levels/soft: banding (soft = blend back to smooth),
    # brush: painterly stroke layer, hue: warm-highlight / cool-shadow shift, normal: normal-map strength
    "toon":    dict(detail=0.45, fine=0.0, levels=5, soft=0.5, brush=0.00, hue=0.35, normal=0.25, rough_var=0.05, wide=1.0),
    "painted": dict(detail=0.80, fine=0.25, levels=0, soft=0.0, brush=0.10, hue=0.70, normal=0.45, rough_var=0.10, wide=1.4),
    "pbr":     dict(detail=1.00, fine=1.0, levels=0, soft=0.0, brush=0.00, hue=0.15, normal=1.00, rough_var=0.25, wide=1.0),
}
WARM = _np.array([1.07, 1.02, 0.90])
COOL = _np.array([0.90, 0.95, 1.10])

def fnoise(n, seed, p=1.0, sx=1.0, sy=1.0, fmin=1.0, fmax=None):
    """Tileable fractal noise in 0..1. p = amplitude falloff (1/f^p); sx/sy > 1 stretch features
    along x (columns, u) / y (rows, v); fmin/fmax in cycles per tile."""
    rng = _np.random.default_rng(seed)
    w = rng.standard_normal((n, n))
    fy = _np.fft.fftfreq(n)[:, None] * n
    fx = _np.fft.fftfreq(n)[None, :] * n
    f = _np.sqrt((fx * sx) ** 2 + (fy * sy) ** 2)
    filt = 1.0 / _np.maximum(f, fmin) ** p
    if fmax:
        filt *= _np.exp(-(f / fmax) ** 2)
    filt[0, 0] = 0
    out = _np.real(_np.fft.ifft2(_np.fft.fft2(w) * filt))
    lo, hi = _np.percentile(out, (1, 99))
    return _np.clip((out - lo) / (hi - lo + 1e-9), 0, 1)

def _grid(n):
    v, u = _np.mgrid[0:n, 0:n] / n          # rows = v, cols = u, both 0..1 over one tile
    return u, v

# ---------------------------------------------------------------- recipes
# Each returns (tone, height, rough_offset, cavity): tone ~ -1..1 brightness variation,
# height 0..1 for the normal map, rough_offset -1..1, cavity 0..1 (1 = open, 0 = crevice).
def r_wood(n, s, st, planks=4, rings=10, seams=True):
    """Planks along u. seams=False -> continuous veneer (grain only, no joints)."""
    u, v = _grid(n)
    warp = fnoise(n, s + 1, p=1.4, sx=6) - 0.5
    grain = _np.sin(2 * _np.pi * (rings * v * planks + 2.5 * warp))
    fibre = fnoise(n, s + 2, p=0.6, sx=24, sy=0.7, fmax=n / 3) - 0.5
    rng = _np.random.default_rng(s + 3)
    pid = _np.floor(v * planks).astype(int) % planks
    ptint = rng.uniform(-1, 1, planks)[pid]
    joint = rng.uniform(0, 1, planks)[pid]                       # one end joint per plank per tile
    fv = (v * planks) % 1.0
    seam = _np.minimum(fv, 1 - fv) < 0.012
    jd = _np.abs(((u - joint) + 0.5) % 1.0 - 0.5) < 0.004
    seams = (seam | jd) if seams else _np.zeros_like(seam)
    tone = 0.30 * grain * st["detail"] + 0.35 * ptint + 0.6 * fibre * st["fine"]
    tone = _np.where(seams, -1.0, tone)
    height = 0.5 + 0.15 * grain * st["detail"] + 0.3 * fibre * st["fine"]
    height = _np.where(seams, 0.0, height)
    return tone, height, 0.4 * fibre * st["fine"], _np.where(seams, 0.3, 1.0)

def r_fabric(n, s, st, weave=96):
    u, v = _grid(n)
    w = (_np.sin(2 * _np.pi * weave * u) * _np.sin(2 * _np.pi * weave * v))
    blot = fnoise(n, s + 1, p=1.6, fmax=12) - 0.5                # crushed-velvet sheen patches
    tone = 0.55 * blot * st["detail"] + 0.12 * w * st["fine"]
    height = 0.5 + 0.25 * w * st["fine"] + 0.15 * blot
    return tone, height, 0.3 * blot, _np.ones_like(u)

def r_brushed(n, s, st):
    streak = fnoise(n, s + 1, p=0.7, sx=40, sy=0.6, fmax=n / 2) - 0.5
    tarnish = fnoise(n, s + 2, p=1.8, fmax=10)
    tarn = _np.clip((tarnish - 0.55) * 3, 0, 1)
    tone = 0.25 * streak * st["fine"] + 0.4 * (tarnish - 0.5) * st["detail"] - 0.5 * tarn * st["detail"]
    height = 0.5 + 0.2 * streak * st["fine"]
    return tone, height, 0.5 * tarn + 0.3 * streak * st["fine"], 1 - 0.3 * tarn

def r_painted_metal(n, s, st):
    base = fnoise(n, s + 1, p=1.7, fmax=16) - 0.5
    chips_n = fnoise(n, s + 2, p=1.1, fmax=n / 4)
    chips = chips_n > 0.86 - 0.06 * (1 - st["detail"])            # worn paint spots
    tone = 0.35 * base * st["detail"]
    tone = _np.where(chips & (st["detail"] > 0.5), -0.7, tone)
    height = 0.5 + 0.1 * base - _np.where(chips, 0.25, 0.0)
    return tone, height, _np.where(chips, -0.5, 0.0) + 0.2 * base, _np.where(chips, 0.6, 1.0)

def r_plaster(n, s, st):
    a = fnoise(n, s + 1, p=1.5, fmax=24) - 0.5
    b = fnoise(n, s + 2, p=0.8, fmax=n / 3) - 0.5
    tone = 0.30 * a * st["detail"] + 0.15 * b * st["fine"]
    return tone, 0.5 + 0.2 * b * st["fine"] + 0.1 * a, 0.2 * a, _np.ones_like(a)

def r_leather(n, s, st):
    c = fnoise(n, s + 1, p=0.9, fmax=n / 4)
    crease = 1 - _np.abs(c - 0.5) * 2                            # ridged noise -> creases
    blot = fnoise(n, s + 2, p=1.6, fmax=10) - 0.5
    tone = 0.4 * blot * st["detail"] - 0.35 * (crease ** 6) * st["fine"]
    return tone, 0.5 + 0.3 * (1 - crease ** 6) * st["fine"], 0.3 * blot, 1 - 0.4 * crease ** 6

def r_marble(n, s, st):
    warp = fnoise(n, s + 1, p=1.5, fmax=20)
    veins = _np.abs(_np.sin(2 * _np.pi * (3 * _grid(n)[0] + 4 * warp)))
    vein = (1 - veins) ** 8
    cloud = fnoise(n, s + 2, p=1.7, fmax=12) - 0.5
    tone = 0.3 * cloud * st["detail"] - 0.6 * vein * st["detail"]
    return tone, 0.5 + 0.05 * cloud, -0.2 * vein, _np.ones_like(cloud)

def r_stone(n, s, st):
    a = fnoise(n, s + 1, p=1.3, fmax=n / 6)
    b = fnoise(n, s + 2, p=0.7, fmax=n / 2) - 0.5
    pits = a < 0.12
    tone = 0.45 * (a - 0.5) * st["detail"] + 0.2 * b * st["fine"] - _np.where(pits, 0.3, 0)
    return tone, 0.3 + 0.5 * a + 0.2 * b * st["fine"], 0.3 * b, _np.where(pits, 0.5, 1.0)

def r_plain(n, s, st):
    a = fnoise(n, s + 1, p=1.6, fmax=12) - 0.5
    return 0.25 * a * st["detail"], 0.5 + 0.05 * a, 0.1 * a, _np.ones_like(a)


# ---------------------------------------------------------------- wallpaper (two-colour printed patterns)
def _soft(d, w):
    """Antialiased step: 1 where d < 0, 0 where d > w."""
    return _np.clip(0.5 - d / max(w, 1e-6), 0, 1)

def _cells(u, v, k, half_drop=False):
    """Local cell coords (-0.5..0.5) on a k x k lattice per tile; half_drop offsets every other column."""
    cu = u * k
    col = _np.floor(cu)
    cv = v * k + (0.5 * (col % 2) if half_drop else 0)
    return (cu % 1.0) - 0.5, (cv % 1.0) - 0.5

def wp_damask(u, v, k, px):
    x, y = _cells(u, v, k, half_drop=True)
    r = _np.sqrt(x * x + (y * 0.85) ** 2); th = _np.arctan2(y, _np.abs(x))
    petals = r - 0.30 * (0.55 + 0.45 * _np.abs(_np.cos(3 * th)))
    body = _soft(petals, px)
    hole = _soft(_np.abs(r - 0.13) - 0.025, px)                    # ring cut into the centre
    stem = _soft(_np.abs(x) - 0.012, px) * _soft(_np.abs(y) - 0.46, px) * (r > 0.3)
    corner = _soft(_np.abs(_np.abs(x) - 0.5) + _np.abs(_np.abs(y) - 0.5) - 0.07, px)   # small diamonds
    return _np.clip(body - hole + stem + corner, 0, 1)

def wp_fans(u, v, k, px):
    """Art Deco sunburst fans in overlapping rows (scales)."""
    cu, cv = u * k, v * k
    m = _np.zeros_like(u)
    for dy, off in ((0.0, 0.0), (0.5, 0.5), (1.0, 0.0)):         # lower rows drawn first, upper rows cover
        x = ((cu + off) % 1.0) - 0.5
        y = (cv % 1.0) - dy + 0.5 - 0.5
        r = _np.sqrt(x * x + y * y)
        inside = (r < 0.5) & (y > 0)
        rays = _soft(_np.abs(((_np.arctan2(y, x) / _np.pi * 11) % 1.0) - 0.5) - 0.12, 0.04)
        rings = _soft(_np.abs(((r * 6) % 1.0) - 0.5) - 0.36, 0.05)
        edge = _soft(_np.abs(r - 0.47) - 0.02, px)
        fan = _np.clip(rays * (r > 0.12) * (r < 0.42) + edge + _soft(r - 0.07, px), 0, 1)
        m = _np.where(inside, fan, m)
    return m

def wp_stripes(u, v, k, px):
    x = (u * k) % 1.0
    wide = _soft(_np.abs(x - 0.5) - 0.18, px)
    pins = _soft(_np.abs(x - 0.12) - 0.012, px) + _soft(_np.abs(x - 0.88) - 0.012, px)
    return _np.clip(wide + pins, 0, 1)

def wp_trellis(u, v, k, px):
    a = (u * k + v * k) % 1.0; b = (u * k - v * k) % 1.0
    lines = _soft(_np.minimum(_np.abs(a - 0.5), _np.abs(b - 0.5)) - 0.025, px * 0.7)
    x, y = _cells(u, v, k)
    r = _np.sqrt(x * x + y * y); th = _np.arctan2(y, x)
    quatre = _soft(r - 0.12 * (0.7 + 0.3 * _np.cos(4 * th)), px)  # quatrefoil in each diamond
    return _np.clip(lines + quatre, 0, 1)

def wp_chevron(u, v, k, px):
    z = (v * k + _np.abs(((u * k) % 1.0) - 0.5)) % 1.0
    return _soft(_np.abs(z - 0.5) - 0.10, px * 1.5)

def wp_floral(u, v, k, px, seed=7):
    rng = _np.random.default_rng(seed)
    m = _np.zeros_like(u)
    for _ in range(3):                                            # 3 jittered flowers per cell
        ox, oy = rng.uniform(0, 1, 2)
        x = ((u * k + ox) % 1.0) - 0.5; y = ((v * k + oy) % 1.0) - 0.5
        r = _np.sqrt(x * x + y * y); th = _np.arctan2(y, x) + rng.uniform(0, 6.28)
        petal = _soft(r - 0.09 * (0.55 + 0.45 * _np.abs(_np.cos(2.5 * th))), px)
        m = _np.maximum(m, petal - _soft(r - 0.022, px))
    return _np.clip(m, 0, 1)

WALLPAPERS = {"damask": wp_damask, "fans": wp_fans, "stripes": wp_stripes, "trellis": wp_trellis,
              "chevron": wp_chevron, "floral": wp_floral}

def r_wallpaper(n, s, st, pattern="damask", ink=(0.8, 0.6, 0.2), repeats=4):
    """Palette colour = paper, ink = printed colour. repeats = pattern repeats per texture tile."""
    u, v = _grid(n)
    mix = WALLPAPERS[pattern](u, v, repeats, 1.5 / n * repeats)
    fibre = fnoise(n, s + 1, p=0.5, fmax=n / 2) - 0.5
    print_var = fnoise(n, s + 2, p=1.4, fmax=20) - 0.5            # uneven ink
    age = fnoise(n, s + 3, p=1.8, fmax=5) - 0.5
    mix = _np.clip(mix * (0.9 + 0.15 * print_var * st["detail"]), 0, 1)
    tone = 0.08 * fibre * st["fine"] + 0.10 * age * st["detail"]
    height = 0.5 + 0.18 * mix * st["detail"] + 0.08 * fibre * st["fine"]   # slightly raised ink
    return tone, height, -0.15 * mix, 1 - 0.05 * mix, (mix, _np.array(ink))

RECIPES = {"wood": r_wood, "fabric": r_fabric, "velvet": r_fabric, "brushed": r_brushed,
           "brass": r_brushed, "painted_metal": r_painted_metal, "plaster": r_plaster,
           "paint": r_plaster, "leather": r_leather, "marble": r_marble, "stone": r_stone,
           "plain": r_plain, "wallpaper": r_wallpaper}

def _posterize(x, levels):
    return _np.round(x * (levels - 1)) / (levels - 1) if levels else x

def make_texture_set(entry, style, n=512, seed=1):
    """Returns dict of float arrays (n x n x 4, rows = v from bottom): albedo (sRGB), normal, mask."""
    name, color, metallic, rough = entry[:4]
    spec = entry[4] if len(entry) > 4 else {}
    st = TEXTURE_STYLES[style]
    fn = RECIPES.get(spec.get("tex", "plain"), r_plain)
    params = {k: v for k, v in spec.items() if k not in ("tex", "tile")}
    s = seed * 1000 + sum(map(ord, name))
    res = fn(n, s, st, **params)
    tone, height, rvar, cav = res[:4]
    base = _np.array(color)[None, None, :]
    if len(res) > 4:                                              # two-colour recipes (wallpaper)
        mix, ink = res[4]
        base = base * (1 - mix[..., None]) + ink[None, None, :] * mix[..., None]
    # broad light/dark variation every material gets (keeps flat areas alive at any style)
    tone = tone + 0.35 * st["wide"] * st["detail"] * (fnoise(n, s + 40, p=1.8, fmax=6) - 0.5) * 2
    if st["brush"]:                                               # painterly strokes: soft, directional
        strokes = fnoise(n, s + 50, p=0.9, sx=4, sy=1.0, fmin=2, fmax=40) - 0.5
        tone = tone + st["brush"] * strokes * 3
    t = _np.clip(tone, -1, 1)
    if st["levels"]:
        q = _posterize((t + 1) / 2, st["levels"]) * 2 - 1
        t = q * (1 - st["soft"]) + t * st["soft"]
    k = 1.0 + t * 0.42
    lin = base * k[..., None]
    if st["hue"]:                                                 # warm lights, cool shadows
        w = _np.clip(t, 0, 1)[..., None] * st["hue"]
        c = _np.clip(-t, 0, 1)[..., None] * st["hue"]
        lin = lin * (1 + (WARM - 1) * w) * (1 + (COOL - 1) * c)
    lin = _np.clip(lin, 0, 1)
    srgb = _np.where(lin <= 0.0031308, lin * 12.92, 1.055 * lin ** (1 / 2.4) - 0.055)
    a = _np.ones((n, n, 1))
    albedo = _np.concatenate([srgb, a], axis=2)
    h = height * st["normal"] * 6.0
    dx = (_np.roll(h, -1, 1) - _np.roll(h, 1, 1)) * 0.5
    dy = (_np.roll(h, -1, 0) - _np.roll(h, 1, 0)) * 0.5
    nrm = _np.dstack([-dx, -dy, _np.ones_like(h)])
    nrm /= _np.linalg.norm(nrm, axis=2, keepdims=True)
    normal = _np.concatenate([nrm * 0.5 + 0.5, a], axis=2)
    r = _np.clip(rough + rvar * st["rough_var"] * 2, 0.02, 1.0)
    mask = _np.dstack([_np.full((n, n), metallic), _np.clip(cav, 0, 1), _np.zeros((n, n)), 1 - r])
    return {"albedo": albedo, "normal": normal, "mask": mask}


