# kit_lib is pasted above this by scripts/assemble.py. Do not import it.



STEEL, BRASS, STAG, SPACER_BLACK, SPACER_RED, ALU = set_palette([
    ("Trn_Steel",       (0.86, 0.87, 0.90), 1.0, 0.06),                                  # polished: no texture, near mirror
    ("Trn_Brass",       (0.95, 0.70, 0.25), 1.0, 0.3, {"tex": "brushed", "tile": 0.5}),
    ("Trn_Stag",        (0.30, 0.09, 0.03), 0.0, 0.55, {"tex": "leather", "tile": 0.04}),  # jigged bone: deep grain
    ("Trn_SpacerBlack", (0.015, 0.012, 0.012), 0.0, 0.35),
    ("Trn_SpacerRed",   (0.40, 0.05, 0.04), 0.0, 0.4),
    ("Trn_Aluminium",   (0.72, 0.73, 0.75), 1.0, 0.32)])


class KnifeAsset(Asset):
    """Render-only, no bevel (millimetre parts)."""
    def finish(self, anchors=False, anchor_group=None):
        if PREVIEW:
            PREVIEW_REGISTRY.append(self)
            return None, []
        mats = palette_materials()
        bpy.ops.object.empty_add(type='PLAIN_AXES', location=(0, 0, 0))
        root = bpy.context.object
        root.name = self.name
        objs = [root]
        if self.D.v:
            objs.append(self.D.build(self.DETAIL_NAME, mats, bevel=0.0, smooth_angle=35))
        for o in objs[1:]:
            o.parent = root
        return root, objs


def smooth(a, b, t):
    k = min(1.0, max(0.0, (t - a) / (b - a)))
    return k * k * (3 - 2 * k)


def ellipse_prism(D, z0, z1, a, b, slot, cx=0.0, n=18):
    """An oval slab from z0 to z1: half-widths a (X) and b (Y), centred on x = cx."""
    import math
    ring = [(cx + a * math.cos(2 * math.pi * k / n), b * math.sin(2 * math.pi * k / n)) for k in range(n)]
    verts = [(x, y, z0) for x, y in ring] + [(x, y, z1) for x, y in ring]
    faces = [list(reversed(range(n))), list(range(n, 2 * n))]
    faces += [[i, (i + 1) % n, n + (i + 1) % n, n + i] for i in range(n)]
    D.add(verts, faces, slot)


def blade(D, z0, length):
    """Single-edged blade from z0 up: per station the spine (x = xs, full thickness) and the edge (x = xe, a hair
    thick), joined by a full flat grind. The edge has a small choil by the guard and a belly that sweeps up into
    a tip leaning towards the spine side."""
    n = 26
    rings = []
    for i in range(n):
        t = i / (n - 1)
        z = z0 + t * length * 0.985
        xs = 0.0075 + 0.0075 * smooth(0.55, 1.0, t)                       # the spine, rising to the upswept tip
        if t < 0.06:
            xe = -0.017                                                    # the choil
        elif t < 0.62:
            xe = -0.0215 - 0.0035 * math.sin(math.pi * 0.5 * min(1.0, (t - 0.06) / 0.5))
        else:
            xe = -0.025 + (0.0145 + 0.025) * ((t - 0.62) / 0.38) ** 1.7    # the belly sweeping up to the tip
        th = 0.0056 * (1.0 - 0.65 * t) + 0.0003                            # thinner towards the tip
        xb = xs - 0.2 * (xs - xe)                                          # where the flat grind meets the spine flat
        rings.append([(xs, th, z), (xb, th * 0.9, z), (xe, 0.00025, z), (xe, -0.00025, z), (xb, -th * 0.9, z), (xs, -th, z)])
    verts = [p for r in rings for p in r] + [(0.0147, 0.0, z0 + length)]
    tip = len(verts) - 1
    m = 6
    faces = [list(reversed(range(m)))]                                     # base, hidden in the guard
    for i in range(n - 1):
        a, b = i * m, (i + 1) * m
        for j in range(m):
            faces.append([a + j, a + (j + 1) % m, b + (j + 1) % m, b + j])
    last = (n - 1) * m
    for j in range(m):
        faces.append([last + j, last + (j + 1) % m, tip])
    D.add(verts, faces, STEEL)


def spacers(D, z_top, down, pattern):
    """A stack of thin spacer rings going `down` from z_top; pattern = [(thickness, slot)], top first."""
    z = z_top
    for th, slot in pattern:
        ellipse_prism(D, z - th, z, 0.0136, 0.0102, slot)
        z -= th
    return z


def knife():
    a = KnifeAsset("Prop_Knife", seed=7)
    D = a.D
    # built with the guard's top at z = 0, then shifted so the pivot is mid-grip
    ellipse_prism(D, -0.004, 0.0, 0.019, 0.0098, BRASS, cx=-0.004, n=20)          # the guard, a thin brass plate
    D.rect(0.009, 0.017, -0.004, 0.004, -0.004, 0.0, BRASS)                          # its lug on the spine side
    blade(D, -0.0005, BLADE)
    stack = [(0.0025, SPACER_BLACK), (0.0012, BRASS), (0.0018, SPACER_RED), (0.0022, SPACER_BLACK), (0.0012, BRASS),
             (0.0018, SPACER_RED), (0.0025, SPACER_BLACK)]
    z = spacers(D, -0.004, True, stack)
    # the stag scales: a slightly fuller oval, with two brass pins showing on both faces
    s0, s1 = z - SCALES, z
    ellipse_prism(D, s0, s1, 0.0142, 0.0108, STAG, n=22)
    for pz in (s1 - 0.016, s0 + 0.016):
        D.lathe([(0.0022, -0.0114), (0.0022, 0.0114)], segs=10, slot=BRASS, center=(0.0, 0.0, pz),
                mat3=Matrix.Rotation(radians(90), 3, 'X'))
    z = spacers(D, s0, True, list(reversed(stack)))
    # the aluminium bird's-head pommel: a cap, then a hooked lump towards the edge side
    ellipse_prism(D, z - 0.012, z, 0.0138, 0.0104, ALU, n=20)
    ellipse_prism(D, z - 0.022, z - 0.012, 0.0125, 0.0098, ALU, cx=-0.004, n=20)
    ellipse_prism(D, z - 0.028, z - 0.016, 0.0085, 0.0092, ALU, cx=-0.016, n=18)    # the hook
    # mid-grip to the pivot
    mid = (s0 + s1) / 2
    D.v = [(x, y, z_ - mid) for x, y, z_ in D.v]
    return a.finish()


import math
run([knife], spacing=1.0)
